    content = f.read()

# Look for patterns like 'height_cm': X and 'publisher_id': Y
heroes = []
for match in re.finditer(r'registration\s+(\d+)', content):
    hero_id = match.group(1)
    start = match.end()
    end = content.find('###', start)
    if end == -1:
        end = content.find('##', start)
    if end == -1:
        end = len(content)
    section = content[start:end]
    height_match = re.search(r"height_cm["':"]*(\d+)", section)
    pub_match = re.search(r"publisher_id["':"]*(\d+)", section)
    height = int(height_match.group(1)) if height_match else None
    pub_id = int(pub_match.group(1)) if pub_match else None
    heroes.append((hero_id, height, pub_id))
    print(f'Hero {hero_id}: height={height}, pub_id={pub_id}')
    if len(heroes) >= 10:
        break
print(f'Total heroes found: {len(heroes)}')

